<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── palette & data ─────────────────────────────────────────────── */
const FIG_BLACK  = '#000000';
const FIG_TEAL   = '#A8DBD2';
const FIG_TEAL6  = '#2F7F76';
const FIG_SALMON = '#E08A66';
const FIG_UNITS  = [6, 7, 8, 10, 50];

const FIG_DATA = [
  [0.03, -0.07], [0.12, 0.18], [0.19, 0.455],
  [0.81, -0.68], [0.91, -0.425], [0.97, -0.475]
];

/* true generating function: smooth wave through control points */
const FIG_CTRL = [
  [0.00, -0.30], [0.06, -0.04], [0.13, 0.22], [0.20, 0.47], [0.26, 0.60],
  [0.33, 0.55], [0.40, 0.36], [0.50, -0.02], [0.60, -0.38], [0.70, -0.60],
  [0.78, -0.65], [0.86, -0.57], [0.93, -0.44], [1.00, -0.30]
];

function figMakeHermite(pts) {
  const n = pts.length, m = new Array(n);
  for (let i = 0; i < n; i++) {
    if (i === 0) m[i] = (pts[1][1] - pts[0][1]) / (pts[1][0] - pts[0][0]);
    else if (i === n - 1) m[i] = (pts[n - 1][1] - pts[n - 2][1]) / (pts[n - 1][0] - pts[n - 2][0]);
    else m[i] = (pts[i + 1][1] - pts[i - 1][1]) / (pts[i + 1][0] - pts[i - 1][0]);
  }
  return function (x) {
    if (x <= pts[0][0]) return pts[0][1];
    if (x >= pts[n - 1][0]) return pts[n - 1][1];
    let i = 0; while (i < n - 2 && x > pts[i + 1][0]) i++;
    const x0 = pts[i][0], x1 = pts[i + 1][0], y0 = pts[i][1], y1 = pts[i + 1][1];
    const h = x1 - x0, t = (x - x0) / h, t2 = t * t, t3 = t2 * t;
    return (2 * t3 - 3 * t2 + 1) * y0 + (t3 - 2 * t2 + t) * h * m[i] +
           (-2 * t3 + 3 * t2) * y1 + (t3 - t2) * h * m[i + 1];
  };
}
const figTrue = figMakeHermite(FIG_CTRL);

const FIG_TRUE_PTS = [];
for (let i = 0; i <= 260; i++) { const x = i / 260; FIG_TRUE_PTS.push({ x: x, y: figTrue(x) }); }

/* piecewise-linear fits (they all pass exactly through the data) */
const FIG_FIT_RAW = [
  /* 6 units — flies off scale across the data-free middle */
  [[0,-0.16],[0.03,-0.07],[0.12,0.18],[0.19,0.455],[0.40,1.60],[0.62,-2.60],
   [0.81,-0.68],[0.86,-0.42],[0.91,-0.425],[0.97,-0.475],[1,-0.50]],
  /* 7 units */
  [[0,-0.22],[0.03,-0.07],[0.12,0.18],[0.19,0.455],[0.28,0.90],[0.45,0.33],[0.72,-1.25],
   [0.81,-0.68],[0.87,-0.40],[0.91,-0.425],[0.97,-0.475],[1,-0.50]],
  /* 8 units */
  [[0,-0.14],[0.03,-0.07],[0.12,0.18],[0.19,0.455],[0.26,0.73],[0.38,0.47],[0.62,-0.42],
   [0.75,-0.86],[0.81,-0.68],[0.88,-0.43],[0.91,-0.425],[0.97,-0.475],[1,-0.49]],
  /* 10 units */
  [[0,-0.22],[0.03,-0.07],[0.12,0.18],[0.19,0.455],[0.27,0.62],[0.36,0.55],[0.46,0.30],
   [0.57,-0.18],[0.68,-0.52],[0.78,-0.69],[0.81,-0.68],[0.87,-0.48],[0.91,-0.425],
   [0.97,-0.475],[1,-0.52]]
];

/* 50 units — close to the true curve but clearly offset from it, still exact at the data */
function figDev(x) {
  return 0.105 * Math.exp(-Math.pow((x - 0.45) / 0.16, 2))
       + 0.045 * Math.exp(-Math.pow((x - 0.29) / 0.09, 2))
       - 0.075 * Math.exp(-Math.pow((x - 0.705) / 0.095, 2))
       - 0.030 * Math.exp(-Math.pow((x - 0.05) / 0.09, 2));
}
function figBase(x) { return figTrue(x) + figDev(x); }
const FIG_CORR = FIG_DATA.map(function (d) { return [d[0], d[1] - figBase(d[0])]; });
function figFit50(x) {
  let y = figBase(x);
  for (let i = 0; i < FIG_CORR.length; i++) {
    y += FIG_CORR[i][1] * Math.exp(-Math.pow((x - FIG_CORR[i][0]) / 0.055, 2));
  }
  return y;
}
const FIG_FIT50 = [];
for (let i = 0; i <= 220; i++) { const x = i / 220; FIG_FIT50.push({ x: x, y: figFit50(x) }); }

const FIG_FITS = FIG_FIT_RAW.map(function (a) {
  return a.map(function (p) { return { x: p[0], y: p[1] }; });
});
FIG_FITS.push(FIG_FIT50);

const FIG_PANELS = [
  { letter: 'a)', title: ' ',               fit: -1 },
  { letter: 'b)', title: '6 hidden units',  fit: 0 },
  { letter: 'c)', title: '7 hidden units',  fit: 1 },
  { letter: 'd)', title: '8 hidden units',  fit: 2 },
  { letter: 'e)', title: '10 hidden units', fit: 3 },
  { letter: 'f)', title: '50 hidden units', fit: 4 }
];

/* ── DOM scaffolding ────────────────────────────────────────────── */
const figContainer = document.getElementById('container');
const figGrid = document.createElement('span');
figGrid.style.cssText = 'display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(2,1fr);' +
  'column-gap:20px;row-gap:10px;width:100%;height:100%;box-sizing:border-box;';
figContainer.appendChild(figGrid);

const figSingleWrap = document.createElement('span');
figSingleWrap.style.cssText = 'display:none;width:100%;height:100%;box-sizing:border-box;';
figContainer.appendChild(figSingleWrap);
const figSingleCanvas = document.createElement('canvas');
figSingleCanvas.style.cssText = 'width:100%;height:100%;display:block';
figSingleWrap.appendChild(figSingleCanvas);

const figCells = [], figGridCharts = [];
let figSingleChart = null;

/* ── responsive sizing ──────────────────────────────────────────── */
function figApplySizes(chart) {
  if (!chart || !chart.options) return;
  const o = chart.options;
  const big = !!(o.plugins.deco && o.plugins.deco.big);
  const s = Math.min(chart.width || 240, chart.height || 200) || 200;
  chart.$s = s;

  const tick = big ? Math.max(9, Math.min(18, s * 0.048)) : Math.max(7.5, Math.min(13, s * 0.055));
  const axT  = big ? Math.max(11, Math.min(22, s * 0.058)) : Math.max(8.5, Math.min(15, s * 0.072));
  const ttl  = big ? Math.max(12, Math.min(24, s * 0.062)) : Math.max(9.5, Math.min(16.5, s * 0.080));
  let   lf   = big ? Math.max(12, Math.min(24, s * 0.062)) : Math.max(9.5, Math.min(16.5, s * 0.082));
  lf = Math.min(lf, ttl * 1.12);                 /* letter fits inside the title band */
  chart.$lf = lf;

  const lw = Math.max(1, s * 0.006);
  o.scales.x.ticks.font.size = tick; o.scales.y.ticks.font.size = tick;
  o.scales.x.title.font.size = axT;  o.scales.y.title.font.size = axT;
  o.plugins.title.font.size = ttl;
  o.scales.x.grid.tickLength = Math.max(3, s * 0.020);
  o.scales.y.grid.tickLength = Math.max(3, s * 0.020);
  o.scales.x.grid.tickWidth = lw; o.scales.y.grid.tickWidth = lw;
  /* generous side padding keeps neighbouring panels' edge tick labels apart */
  o.layout.padding = {
    top: 2,
    left: big ? 6 : Math.max(8, tick * 0.9),
    right: big ? 10 : Math.max(10, tick * 1.1),
    bottom: 0
  };
  chart.data.datasets.forEach(function (d) {
    if (d.__kind === 'true') d.borderWidth = Math.max(1.4, s * 0.0165);
    else if (d.__kind === 'fit') d.borderWidth = Math.max(1.8, s * 0.0235);
    else if (d.__kind === 'fit2') d.borderWidth = Math.max(1.4, s * 0.0155);
    else if (d.__kind === 'dots') {
      d.pointRadius = Math.max(2.5, s * 0.030);
      d.pointHoverRadius = Math.max(3, s * 0.034);
    }
  });
  chart.update('none');
}

/* ── decoration plugin: frame, panel letter, band, overlay legend ─ */
const figDeco = {
  id: 'deco',
  beforeDraw: function (chart) {
    const s = Math.min(chart.width, chart.height);
    if (Math.abs((chart.$s || 0) - s) > 1.5 && !chart.$pend) {
      chart.$pend = true;
      requestAnimationFrame(function () { chart.$pend = false; figApplySizes(chart); });
    }
  },
  beforeDatasetsDraw: function (chart, args, opts) {
    if (!opts || !opts.big) return;
    const ca = chart.chartArea, ctx = chart.ctx;
    const x0 = chart.scales.x.getPixelForValue(0.22);
    const x1 = chart.scales.x.getPixelForValue(0.78);
    ctx.save();
    ctx.fillStyle = 'rgba(140,155,175,0.13)';
    ctx.fillRect(x0, ca.top, x1 - x0, ca.bottom - ca.top);
    ctx.restore();
  },
  afterDatasetsDraw: function (chart, args, opts) {
    const ctx = chart.ctx, ca = chart.chartArea;
    const s = Math.min(chart.width, chart.height);
    ctx.save();

    /* panel frame */
    ctx.strokeStyle = '#000';
    ctx.lineWidth = Math.max(1, s * 0.006);
    ctx.strokeRect(ca.left, ca.top, ca.right - ca.left, ca.bottom - ca.top);

    /* panel letter — ABOVE the frame, aligned with the title row */
    const lf = chart.$lf || Math.max(9, s * 0.08);
    ctx.font = '700 ' + lf + 'px sans-serif';
    ctx.fillStyle = '#000'; ctx.textAlign = 'left'; ctx.textBaseline = 'top';
    ctx.fillText(opts.letter, 1, 1);

    /* data-free band label (single-panel view only) */
    if (opts.big) {
      const fs = Math.max(9, Math.min(17, s * 0.040));
      const cx = (chart.scales.x.getPixelForValue(0.22) + chart.scales.x.getPixelForValue(0.78)) / 2;
      const cy = ca.bottom - fs * 1.5;
      ctx.font = fs + 'px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      const txt = 'no training data here';
      const w = ctx.measureText(txt).width;
      ctx.fillStyle = 'rgba(255,255,255,0.94)';
      ctx.fillRect(cx - w / 2 - 6, cy - fs * 0.85, w + 12, fs * 1.7);
      ctx.fillStyle = '#55606e';
      ctx.fillText(txt, cx, cy);
    }

    /* overlay legend, parked in empty top-right space */
    if (opts.overlay) {
      const fs = Math.max(9, Math.min(16, s * 0.040));
      const items = [['50 hidden units', FIG_TEAL], ['6 hidden units', FIG_TEAL6]];
      ctx.font = fs + 'px sans-serif'; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
      let w = 0;
      items.forEach(function (it) { w = Math.max(w, ctx.measureText(it[0]).width); });
      const lineW = fs * 1.8, pad = fs * 0.55;
      const bw = w + lineW + pad * 3, bh = items.length * fs * 1.7 + pad;
      const bx = ca.right - bw - pad * 1.4, by = ca.top + pad * 1.4;
      ctx.fillStyle = 'rgba(255,255,255,0.92)'; ctx.fillRect(bx, by, bw, bh);
      items.forEach(function (it, i) {
        const yy = by + pad / 2 + fs * 0.9 + i * fs * 1.7;
        ctx.strokeStyle = it[1]; ctx.lineWidth = Math.max(2, s * 0.011);
        ctx.beginPath(); ctx.moveTo(bx + pad, yy); ctx.lineTo(bx + pad + lineW, yy); ctx.stroke();
        ctx.fillStyle = '#222'; ctx.fillText(it[0], bx + pad * 2 + lineW, yy);
      });
    }
    ctx.restore();
  }
};

/* ── chart factory ──────────────────────────────────────────────── */
function figMakeChart(canvas, idx, big, overlay, showY, showXTitle) {
  const p = FIG_PANELS[idx];
  const ds = [];
  ds.push({
    __kind: 'dots', label: 'Training data', type: 'scatter', order: 0,
    data: FIG_DATA.map(function (d) { return { x: d[0], y: d[1] }; }),
    backgroundColor: FIG_SALMON, borderWidth: 0, pointRadius: 5, pointHoverRadius: 6
  });
  if (big && overlay) {
    ds.push({ __kind: 'fit', label: '50 hidden units', order: 1, data: FIG_FITS[4],
      borderColor: FIG_TEAL, backgroundColor: 'transparent', borderWidth: 4,
      pointRadius: 0, pointHitRadius: 0, tension: 0, borderJoinStyle: 'round', borderCapStyle: 'round' });
    ds.push({ __kind: 'fit2', label: '6 hidden units', order: 1, data: FIG_FITS[0],
      borderColor: FIG_TEAL6, backgroundColor: 'transparent', borderWidth: 3,
      pointRadius: 0, pointHitRadius: 0, tension: 0, borderJoinStyle: 'round', borderCapStyle: 'round' });
  } else if (p.fit >= 0) {
    ds.push({ __kind: 'fit', label: FIG_UNITS[p.fit] + '-unit network fit', order: 1, data: FIG_FITS[p.fit],
      borderColor: FIG_TEAL, backgroundColor: 'transparent', borderWidth: 4,
      pointRadius: 0, pointHitRadius: 0, tension: 0, borderJoinStyle: 'round', borderCapStyle: 'round' });
  }
  ds.push({ __kind: 'true', label: 'True function', order: 2, data: FIG_TRUE_PTS,
    borderColor: FIG_BLACK, backgroundColor: 'transparent', borderWidth: 3.2,
    pointRadius: 0, pointHitRadius: 0, tension: 0, borderJoinStyle: 'round', borderCapStyle: 'round' });

  const chart = new Chart(canvas.getContext('2d'), {
    type: 'line',
    data: { datasets: ds },
    options: {
      responsive: true, maintainAspectRatio: false,
      animation: { duration: 260 },
      layout: { padding: { top: 2, left: 8, right: 10, bottom: 0 } },
      interaction: { mode: 'nearest', intersect: true },
      plugins: {
        legend: { display: false },
        tooltip: { enabled: false },
        title: {
          display: true,
          text: (big && overlay) ? '6 vs 50 hidden units' : p.title,
          color: '#000', font: { size: 14, weight: '400', family: 'sans-serif' },
          padding: { top: 0, bottom: 4 }
        },
        deco: { letter: p.letter, big: !!big, overlay: !!(big && overlay) }
      },
      scales: {
        x: {
          type: 'linear', min: 0, max: 1,
          afterBuildTicks: function (a) { a.ticks = [{ value: 0 }, { value: 0.5 }, { value: 1 }]; },
          ticks: { callback: function (v) { return Number(v).toFixed(1); },
                   color: '#000', font: { size: 11, family: 'sans-serif' },
                   padding: 2, maxRotation: 0, autoSkip: false },
          grid: { drawOnChartArea: false, drawTicks: true, tickLength: 5, tickColor: '#000', tickWidth: 1.3, color: 'transparent' },
          border: { display: false },
          title: { display: !!showXTitle, text: 'Input, x', color: '#000',
                   font: { size: 14, family: 'sans-serif' }, padding: { top: 1, bottom: 0 } }
        },
        y: {
          type: 'linear', min: -1, max: 1,
          afterBuildTicks: function (a) { a.ticks = [{ value: -1 }, { value: 0 }, { value: 1 }]; },
          ticks: { display: !!showY, callback: function (v) { return Number(v).toFixed(1); },
                   color: '#000', font: { size: 11, family: 'sans-serif' }, padding: 2, autoSkip: false },
          grid: { drawOnChartArea: false, drawTicks: true, tickLength: 5, tickColor: '#000', tickWidth: 1.3, color: 'transparent' },
          border: { display: false },
          title: { display: !!showY, text: 'Output, y', color: '#000', font: { size: 14, family: 'sans-serif' } }
        }
      }
    },
    plugins: [figDeco]
  });

  canvas.addEventListener('mousemove', function (e) {
    const hits = chart.getElementsAtEventForMode(e, 'nearest', { intersect: true }, true);
    let dot = null;
    for (let i = 0; i < hits.length; i++) {
      if (chart.data.datasets[hits[i].datasetIndex].__kind === 'dots') { dot = hits[i]; break; }
    }
    if (dot) {
      const pt = chart.data.datasets[dot.datasetIndex].data[dot.index];
      showTooltip('Training point  x = ' + pt.x.toFixed(2) + ',  y = ' + pt.y.toFixed(2) +
                  '  —  every fit passes exactly through it', e);
      canvas.style.cursor = 'pointer';
    } else if (!big) {
      showTooltip(idx === 0 ? 'The true function and the training data'
                            : 'Click to enlarge the ' + FIG_UNITS[FIG_PANELS[idx].fit] + '-unit panel', e);
      canvas.style.cursor = 'pointer';
    } else { hideTooltip(); canvas.style.cursor = 'default'; }
  });
  canvas.addEventListener('mouseleave', hideTooltip);
  canvas.addEventListener('click', function (e) {
    const hits = chart.getElementsAtEventForMode(e, 'nearest', { intersect: true }, true);
    for (let i = 0; i < hits.length; i++) {
      if (chart.data.datasets[hits[i].datasetIndex].__kind === 'dots') {
        showPopup('A training point',
          'All six networks reproduce this point exactly — the fits differ only between the points. ' +
          'Because the data cluster at the two ends, the middle of the input range is completely unconstrained, ' +
          'and that is where capacity shows its effect.');
        return;
      }
    }
    if (!big) {
      if (idx === 0) {
        showPopup('The target and the data',
          'The black curve is the function we are trying to learn; the orange dots are the only information the ' +
          'network ever sees. Three points sit below x = 0.2 and three above x = 0.8, leaving a wide gap with no data.');
      } else { figSelectPanel(idx); }
    }
  });

  figApplySizes(chart);
  return chart;
}

/* ── build the 3 × 2 grid ───────────────────────────────────────── */
for (let i = 0; i < 6; i++) {
  const cell = document.createElement('span');
  cell.style.cssText = 'display:block;position:relative;min-width:0;min-height:0;border-radius:5px;';
  const cv = document.createElement('canvas');
  cv.style.cssText = 'width:100%;height:100%;display:block';
  cell.appendChild(cv);
  figGrid.appendChild(cell);
  figCells.push(cell);
  figGridCharts.push(figMakeChart(cv, i, false, false, (i % 3 === 0), (i >= 3)));
}

/* ── state & rendering ──────────────────────────────────────────── */
const figState = { unitIdx: 0, single: false, overlay: false, showHighlight: false };

function figRender() {
  figGrid.style.display = figState.single ? 'none' : 'grid';
  figSingleWrap.style.display = figState.single ? 'block' : 'none';
  if (figSingleChart) { figSingleChart.destroy(); figSingleChart = null; }
  if (figState.single) {
    figSingleChart = figMakeChart(figSingleCanvas, figState.unitIdx + 1, true, figState.overlay, true, true);
  } else {
    for (let i = 0; i < figCells.length; i++) {
      const on = figState.showHighlight && (i === figState.unitIdx + 1);
      figCells[i].style.background = on ? '#eaf5fb' : 'transparent';
      figCells[i].style.boxShadow = on ? '0 0 0 2px #7cc0e4' : 'none';
    }
    figGridCharts.forEach(function (c) { c.resize(); figApplySizes(c); });
  }
}

function figSelectPanel(idx) {
  figState.unitIdx = Math.max(0, Math.min(4, idx - 1));
  figState.single = true;
  figState.showHighlight = true;
  document.getElementById('hiddenUnitsInput').value = figState.unitIdx;
  document.getElementById('hiddenUnitsVal').value = FIG_UNITS[figState.unitIdx];
  document.getElementById('layoutInput').checked = true;
  figRender();
}

/* ── controls ───────────────────────────────────────────────────── */
function update_hiddenUnits(v) {
  figState.unitIdx = Math.max(0, Math.min(4, v | 0));
  figState.showHighlight = true;
  document.getElementById('hiddenUnitsVal').value = FIG_UNITS[figState.unitIdx];
  figRender();
}
function toggle_layout(on) { figState.single = !!on; figRender(); }
function toggle_overlay6vs50(on) {
  figState.overlay = !!on;
  if (on && !figState.single) {
    figState.single = true;
    document.getElementById('layoutInput').checked = true;
  }
  figRender();
}
function showKeyInsight() {
  showPopup('Key insight',
    'Over-parameterisation does not make a network wigglier. Every one of these models fits the same data points ' +
    'exactly, but the ones with far more hidden units than data choose the smoothest such function — so the 50-unit ' +
    'fit generalises best, while the barely-sufficient 6-unit fit flails in the region with no data.');
}

