// @FIGURE_CODE_BEGIN
/* ── palette, fonts & data ──────────────────────────────────────── */
const FIG_BLACK  = '#000000';
const FIG_TEAL   = '#A8DBD2';
const FIG_TEAL6  = '#2E7F76';
const FIG_SALMON = '#E08A66';
const FIG_FONT   = '"Segoe UI","Helvetica Neue",Helvetica,Arial,sans-serif';
const FIG_UNITS  = [6, 7, 8, 10, 50];

const FIG_DATA = [
  [0.03, -0.07], [0.12, 0.18], [0.19, 0.455],
  [0.81, -0.68], [0.91, -0.425], [0.97, -0.475]
];

/* true generating function: smooth wave through control points */
const FIG_CTRL = [
  [0.00, -0.30], [0.06, -0.04], [0.13, 0.22], [0.20, 0.47], [0.26, 0.60],
  [0.33, 0.55], [0.40, 0.36], [0.50, -0.02], [0.60, -0.38], [0.70, -0.60],
  [0.78, -0.65], [0.86, -0.57], [0.93, -0.44], [1.00, -0.30]
];

function figMakeHermite(pts) {
  const n = pts.length, m = new Array(n);
  for (let i = 0; i < n; i++) {
    if (i === 0) m[i] = (pts[1][1] - pts[0][1]) / (pts[1][0] - pts[0][0]);
    else if (i === n - 1) m[i] = (pts[n - 1][1] - pts[n - 2][1]) / (pts[n - 1][0] - pts[n - 2][0]);
    else m[i] = (pts[i + 1][1] - pts[i - 1][1]) / (pts[i + 1][0] - pts[i - 1][0]);
  }
  return function (x) {
    if (x <= pts[0][0]) return pts[0][1];
    if (x >= pts[n - 1][0]) return pts[n - 1][1];
    let i = 0; while (i < n - 2 && x > pts[i + 1][0]) i++;
    const x0 = pts[i][0], x1 = pts[i + 1][0], y0 = pts[i][1], y1 = pts[i + 1][1];
    const h = x1 - x0, t = (x - x0) / h, t2 = t * t, t3 = t2 * t;
    return (2 * t3 - 3 * t2 + 1) * y0 + (t3 - 2 * t2 + t) * h * m[i] +
           (-2 * t3 + 3 * t2) * y1 + (t3 - t2) * h * m[i + 1];
  };
}
const figTrue = figMakeHermite(FIG_CTRL);

const FIG_TRUE_PTS = [];
for (let i = 0; i <= 300; i++) { const x = i / 300; FIG_TRUE_PTS.push({ x: x, y: figTrue(x) }); }

/* piecewise-linear fits (all pass exactly through the data) */
const FIG_FIT_RAW = [
  /* 6 units — flies off scale across the data-free middle */
  [[0,-0.16],[0.03,-0.07],[0.12,0.18],[0.19,0.455],[0.40,1.75],[0.62,-2.80],
   [0.81,-0.68],[0.86,-0.42],[0.91,-0.425],[0.97,-0.475],[1,-0.50]],
  /* 7 units */
  [[0,-0.22],[0.03,-0.07],[0.12,0.18],[0.19,0.455],[0.28,0.90],[0.45,0.33],[0.72,-1.30],
   [0.81,-0.68],[0.87,-0.40],[0.91,-0.425],[0.97,-0.475],[1,-0.50]],
  /* 8 units */
  [[0,-0.14],[0.03,-0.07],[0.12,0.18],[0.19,0.455],[0.26,0.73],[0.38,0.47],[0.62,-0.42],
   [0.75,-0.86],[0.81,-0.68],[0.88,-0.43],[0.91,-0.425],[0.97,-0.475],[1,-0.49]],
  /* 10 units */
  [[0,-0.22],[0.03,-0.07],[0.12,0.18],[0.19,0.455],[0.27,0.62],[0.36,0.55],[0.46,0.30],
   [0.57,-0.18],[0.68,-0.52],[0.78,-0.69],[0.81,-0.68],[0.87,-0.48],[0.91,-0.425],
   [0.97,-0.475],[1,-0.52]]
];

/* 50 units — close to the truth but slightly offset, still exact at the data */
function figDev(x) {
  return 0.105 * Math.exp(-Math.pow((x - 0.45) / 0.16, 2))
       + 0.045 * Math.exp(-Math.pow((x - 0.29) / 0.09, 2))
       - 0.075 * Math.exp(-Math.pow((x - 0.705) / 0.095, 2))
       - 0.030 * Math.exp(-Math.pow((x - 0.05) / 0.09, 2));
}
function figBase(x) { return figTrue(x) + figDev(x); }
const FIG_CORR = FIG_DATA.map(function (d) { return [d[0], d[1] - figBase(d[0])]; });
function figFit50(x) {
  let y = figBase(x);
  for (let i = 0; i < FIG_CORR.length; i++) {
    y += FIG_CORR[i][1] * Math.exp(-Math.pow((x - FIG_CORR[i][0]) / 0.055, 2));
  }
  return y;
}
const FIG_FIT50 = [];
for (let i = 0; i <= 240; i++) { const x = i / 240; FIG_FIT50.push({ x: x, y: figFit50(x) }); }

const FIG_FITS = FIG_FIT_RAW.map(function (a) {
  return a.map(function (p) { return { x: p[0], y: p[1] }; });
});
FIG_FITS.push(FIG_FIT50);

const FIG_PANELS = [
  { letter: 'a)', title: ' ',               fit: -1 },
  { letter: 'b)', title: '6 hidden units',  fit: 0 },
  { letter: 'c)', title: '7 hidden units',  fit: 1 },
  { letter: 'd)', title: '8 hidden units',  fit: 2 },
  { letter: 'e)', title: '10 hidden units', fit: 3 },
  { letter: 'f)', title: '50 hidden units', fit: 4 }
];

/* ── DOM scaffolding ────────────────────────────────────────────── */
const figContainer = document.getElementById('container');
const figGrid = document.createElement('span');
figGrid.style.cssText = 'display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(2,1fr);' +
  'column-gap:18px;row-gap:12px;width:100%;height:100%;box-sizing:border-box;';
figContainer.appendChild(figGrid);

const figSingleWrap = document.createElement('span');
figSingleWrap.style.cssText = 'display:none;width:100%;height:100%;box-sizing:border-box;';
figContainer.appendChild(figSingleWrap);
const figSingleCanvas = document.createElement('canvas');
figSingleCanvas.style.cssText = 'width:100%;height:100%;display:block';
figSingleWrap.appendChild(figSingleCanvas);

const figCells = [], figGridCharts = [];
let figSingleChart = null;

/* ── scale-aware style ──────────────────────────────────────────── */
function figClamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function figStyle(chart) {
  const big = !!chart.$big;
  const s = Math.min(chart.width || 240, chart.height || 200) || 200;
  return {
    s: s,
    tick:  figClamp(s * 0.068, 8,   big ? 22 : 15),
    axT:   figClamp(s * 0.086, 9,   big ? 26 : 17.5),
    ttl:   figClamp(s * 0.082, 9.5, big ? 26 : 17.5),
    lf:    figClamp(s * 0.092, 10,  big ? 28 : 18.5),
    frame: Math.max(1,   s * 0.0075),
    trueW: Math.max(1.8, s * 0.0235),
    fitW:  Math.max(2.2, s * 0.0285),
    fit2W: Math.max(1.8, s * 0.0215),
    dotR:  Math.max(2.6, s * 0.0335)
  };
}

function figApplySizes(chart) {
  if (!chart || !chart.options) return;
  const st = figStyle(chart);
  const o = chart.options;
  chart.$appliedS = st.s;
  o.scales.x.ticks.font.size = st.tick;
  o.scales.y.ticks.font.size = st.tick;
  o.scales.x.title.font.size = st.axT;
  o.scales.y.title.font.size = st.axT;
  o.plugins.title.font.size = st.ttl;
  o.scales.x.grid.tickLength = Math.max(3, st.s * 0.022);
  o.scales.y.grid.tickLength = Math.max(3, st.s * 0.022);
  o.scales.x.grid.tickWidth = st.frame;
  o.scales.y.grid.tickWidth = st.frame;
  o.layout.padding = {
    top: 2,
    left: chart.$showY ? 3 : Math.max(8, st.tick * 1.15),
    right: Math.max(10, st.tick * 1.3),
    bottom: 0
  };
  chart.update('none');
}

/* ── drawing helpers ────────────────────────────────────────────── */
function figStrokeSeries(ctx, chart, pts, color, width, alpha) {
  const sx = chart.scales.x, sy = chart.scales.y;
  ctx.save();
  ctx.globalAlpha = (alpha == null) ? 1 : alpha;
  ctx.beginPath();
  for (let i = 0; i < pts.length; i++) {
    const X = sx.getPixelForValue(pts[i].x), Y = sy.getPixelForValue(pts[i].y);
    if (i === 0) ctx.moveTo(X, Y); else ctx.lineTo(X, Y);
  }
  ctx.strokeStyle = color; ctx.lineWidth = width;
  ctx.lineJoin = 'round'; ctx.lineCap = 'round';
  ctx.stroke();
  ctx.restore();
}

function figDrawMixed(ctx, roman, italic, cx, cy, size, color, rotate) {
  ctx.save();
  ctx.translate(cx, cy);
  if (rotate) ctx.rotate(-Math.PI / 2);
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'left';
  ctx.font = size + 'px ' + FIG_FONT;
  const w1 = ctx.measureText(roman).width;
  ctx.font = 'italic ' + size + 'px ' + FIG_FONT;
  const w2 = ctx.measureText(italic).width;
  let x = -(w1 + w2) / 2;
  ctx.fillStyle = color;
  ctx.font = size + 'px ' + FIG_FONT;
  ctx.fillText(roman, x, 0);
  ctx.font = 'italic ' + size + 'px ' + FIG_FONT;
  ctx.fillText(italic, x + w1, 0);
  ctx.restore();
}

/* ── the one plugin that draws every mark (deterministic z-order) ─ */
const figDeco = {
  id: 'deco',
  beforeDraw: function (chart) {
    const s = Math.min(chart.width, chart.height);
    if (Math.abs((chart.$appliedS || 0) - s) > 1.5 && !chart.$pend) {
      chart.$pend = true;
      requestAnimationFrame(function () { chart.$pend = false; figApplySizes(chart); });
    }
  },
  afterDatasetsDraw: function (chart, args, opts) {
    const ctx = chart.ctx, ca = chart.chartArea, st = figStyle(chart);
    const big = !!opts.big, overlay = !!opts.overlay;
    const alpha = (chart.$alpha == null) ? 1 : chart.$alpha;

    /* data-free band (single-panel view) */
    if (big) {
      const x0 = chart.scales.x.getPixelForValue(0.22);
      const x1 = chart.scales.x.getPixelForValue(0.78);
      ctx.save();
      ctx.fillStyle = 'rgba(140,155,175,0.13)';
      ctx.fillRect(x0, ca.top, x1 - x0, ca.bottom - ca.top);
      ctx.restore();
    }

    /* clipped data marks: black truth → teal fit → orange dots */
    ctx.save();
    ctx.beginPath();
    ctx.rect(ca.left, ca.top, ca.right - ca.left, ca.bottom - ca.top);
    ctx.clip();

    figStrokeSeries(ctx, chart, FIG_TRUE_PTS, FIG_BLACK, st.trueW, 1);

    if (big && overlay) {
      figStrokeSeries(ctx, chart, FIG_FITS[4], FIG_TEAL, st.fitW, alpha);
      figStrokeSeries(ctx, chart, FIG_FITS[0], FIG_TEAL6, st.fit2W, alpha);
    } else if (opts.fit >= 0) {
      figStrokeSeries(ctx, chart, FIG_FITS[opts.fit], FIG_TEAL, st.fitW, alpha);
    }

    for (let i = 0; i < FIG_DATA.length; i++) {
      const X = chart.scales.x.getPixelForValue(FIG_DATA[i][0]);
      const Y = chart.scales.y.getPixelForValue(FIG_DATA[i][1]);
      ctx.beginPath();
      ctx.arc(X, Y, st.dotR, 0, Math.PI * 2);
      ctx.fillStyle = (chart.$hover === i) ? '#c96f49' : FIG_SALMON;
      ctx.fill();
    }
    ctx.restore();

    /* panel frame */
    ctx.save();
    ctx.strokeStyle = '#000';
    ctx.lineWidth = st.frame;
    ctx.strokeRect(ca.left, ca.top, ca.right - ca.left, ca.bottom - ca.top);

    /* panel letter, above the frame in the title band */
    ctx.font = '600 ' + st.lf + 'px ' + FIG_FONT;
    ctx.fillStyle = '#000'; ctx.textAlign = 'left'; ctx.textBaseline = 'top';
    ctx.fillText(opts.letter, 1, 1);
    ctx.restore();

    /* axis titles with italic variable names */
    if (chart.$showXTitle) {
      figDrawMixed(ctx, 'Input, ', 'x',
        (ca.left + ca.right) / 2, chart.scales.x.bottom - st.axT * 0.58,
        st.axT, '#000', false);
    }
    if (chart.$showY) {
      figDrawMixed(ctx, 'Output, ', 'y',
        chart.scales.y.left + st.axT * 0.62, (ca.top + ca.bottom) / 2,
        st.axT, '#000', true);
    }

    /* data-free band label */
    if (big) {
      const fs = figClamp(st.s * 0.042, 9, 17);
      const cx = (chart.scales.x.getPixelForValue(0.22) + chart.scales.x.getPixelForValue(0.78)) / 2;
      const cy = ca.bottom - fs * 1.6;
      ctx.save();
      ctx.font = fs + 'px ' + FIG_FONT; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      const txt = 'no training data here';
      const w = ctx.measureText(txt).width;
      ctx.fillStyle = 'rgba(255,255,255,0.94)';
      ctx.fillRect(cx - w / 2 - 6, cy - fs * 0.9, w + 12, fs * 1.8);
      ctx.fillStyle = '#55606e';
      ctx.fillText(txt, cx, cy);
      ctx.restore();
    }

    /* overlay legend, parked in empty top-right space */
    if (big && overlay) {
      const fs = figClamp(st.s * 0.042, 9, 16);
      const items = [['50 hidden units', FIG_TEAL], ['6 hidden units', FIG_TEAL6]];
      ctx.save();
      ctx.font = fs + 'px ' + FIG_FONT; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
      let w = 0;
      items.forEach(function (it) { w = Math.max(w, ctx.measureText(it[0]).width); });
      const lineW = fs * 1.9, pad = fs * 0.6;
      const bw = w + lineW + pad * 3, bh = items.length * fs * 1.8 + pad;
      const bx = ca.right - bw - pad * 1.4, by = ca.top + pad * 1.4;
      ctx.fillStyle = 'rgba(255,255,255,0.93)'; ctx.fillRect(bx, by, bw, bh);
      items.forEach(function (it, i) {
        const yy = by + pad / 2 + fs * 0.95 + i * fs * 1.8;
        ctx.strokeStyle = it[1]; ctx.lineWidth = Math.max(2.4, st.s * 0.012);
        ctx.lineCap = 'round';
        ctx.beginPath(); ctx.moveTo(bx + pad, yy); ctx.lineTo(bx + pad + lineW, yy); ctx.stroke();
        ctx.fillStyle = '#222'; ctx.fillText(it[0], bx + pad * 2 + lineW, yy);
      });
      ctx.restore();
    }
  }
};

/* ── chart factory (axes only; all marks come from figDeco) ─────── */
function figMakeChart(canvas, idx, big, overlay, showY, showXTitle) {
  const p = FIG_PANELS[idx];
  const chart = new Chart(canvas.getContext('2d'), {
    type: 'scatter',
    data: { datasets: [] },
    options: {
      responsive: true, maintainAspectRatio: false,
      animation: false,
      events: [],
      layout: { padding: { top: 2, left: 8, right: 10, bottom: 0 } },
      plugins: {
        legend: { display: false },
        tooltip: { enabled: false },
        title: {
          display: true,
          text: (big && overlay) ? '6 vs 50 hidden units' : p.title,
          color: '#000', font: { size: 14, weight: '400', family: FIG_FONT },
          padding: { top: 0, bottom: 5 }
        },
        deco: { letter: p.letter, big: !!big, overlay: !!(big && overlay), fit: p.fit }
      },
      scales: {
        x: {
          type: 'linear', min: 0, max: 1,
          afterBuildTicks: function (a) { a.ticks = [{ value: 0 }, { value: 0.5 }, { value: 1 }]; },
          ticks: {
            callback: function (v) { return Number(v).toFixed(1); },
            color: '#000', font: { size: 11, family: FIG_FONT },
            padding: 2, maxRotation: 0, autoSkip: false
          },
          grid: { drawOnChartArea: false, drawTicks: true, tickLength: 5, tickColor: '#000', tickWidth: 1.3, color: 'transparent' },
          border: { display: false },
          title: {
            display: !!showXTitle, text: 'Input, x', color: 'rgba(0,0,0,0)',
            font: { size: 14, family: FIG_FONT }, padding: { top: 1, bottom: 1 }
          }
        },
        y: {
          type: 'linear', min: -1, max: 1,
          afterBuildTicks: function (a) { a.ticks = [{ value: -1 }, { value: 0 }, { value: 1 }]; },
          ticks: {
            display: !!showY, callback: function (v) { return Number(v).toFixed(1); },
            color: '#000', font: { size: 11, family: FIG_FONT }, padding: 2, autoSkip: false
          },
          grid: { drawOnChartArea: false, drawTicks: true, tickLength: 5, tickColor: '#000', tickWidth: 1.3, color: 'transparent' },
          border: { display: false },
          title: {
            display: !!showY, text: 'Output, y', color: 'rgba(0,0,0,0)',
            font: { size: 14, family: FIG_FONT }, padding: { top: 1, bottom: 1 }
          }
        }
      }
    },
    plugins: [figDeco]
  });

  chart.$big = !!big;
  chart.$showY = !!showY;
  chart.$showXTitle = !!showXTitle;
  chart.$hover = -1;

  /* manual hit-testing for the training dots */
  function figHitDot(evt) {
    const rect = canvas.getBoundingClientRect();
    const px = evt.clientX - rect.left, py = evt.clientY - rect.top;
    const r = figStyle(chart).dotR + 3;
    for (let i = 0; i < FIG_DATA.length; i++) {
      const X = chart.scales.x.getPixelForValue(FIG_DATA[i][0]);
      const Y = chart.scales.y.getPixelForValue(FIG_DATA[i][1]);
      if ((px - X) * (px - X) + (py - Y) * (py - Y) <= r * r) return i;
    }
    return -1;
  }

  canvas.addEventListener('mousemove', function (e) {
    const hit = figHitDot(e);
    if (hit !== chart.$hover) { chart.$hover = hit; chart.update('none'); }
    if (hit >= 0) {
      showTooltip('Training point  x = ' + FIG_DATA[hit][0].toFixed(2) +
                  ',  y = ' + FIG_DATA[hit][1].toFixed(2) +
                  '  —  every fit passes exactly through it', e);
      canvas.style.cursor = 'pointer';
    } else if (!big) {
      showTooltip(idx === 0 ? 'The true function and the training data'
                            : 'Click to enlarge the ' + FIG_UNITS[FIG_PANELS[idx].fit] + '-unit panel', e);
      canvas.style.cursor = 'pointer';
    } else { hideTooltip(); canvas.style.cursor = 'default'; }
  });
  canvas.addEventListener('mouseleave', function () {
    hideTooltip();
    if (chart.$hover !== -1) { chart.$hover = -1; chart.update('none'); }
  });
  canvas.addEventListener('click', function (e) {
    if (figHitDot(e) >= 0) {
      showPopup('A training point',
        'All six networks reproduce this point exactly — the fits differ only between the points. ' +
        'Because the data cluster at the two ends, the middle of the input range is completely unconstrained, ' +
        'and that is where capacity shows its effect.');
      return;
    }
    if (!big) {
      if (idx === 0) {
        showPopup('The target and the data',
          'The black curve is the function we are trying to learn; the orange dots are the only information the ' +
          'network ever sees. Three points sit below x = 0.2 and three above x = 0.8, leaving a wide gap with no data.');
      } else { figSelectPanel(idx); }
    }
  });

  figApplySizes(chart);
  return chart;
}

/* ── short opacity fade for the fitted curve ────────────────────── */
function figFadeIn(chart) {
  chart.$alpha = 0;
  const t0 = performance.now();
  (function step() {
    if (!chart.ctx) return;
    const k = Math.min(1, (performance.now() - t0) / 260);
    chart.$alpha = k;
    chart.update('none');
    if (k < 1) requestAnimationFrame(step);
  })();
}

/* ── build the 3 × 2 grid ───────────────────────────────────────── */
for (let i = 0; i < 6; i++) {
  const cell = document.createElement('span');
  cell.style.cssText = 'display:block;position:relative;min-width:0;min-height:0;border-radius:5px;';
  const cv = document.createElement('canvas');
  cv.style.cssText = 'width:100%;height:100%;display:block';
  cell.appendChild(cv);
  figGrid.appendChild(cell);
  figCells.push(cell);
  figGridCharts.push(figMakeChart(cv, i, false, false, (i % 3 === 0), (i >= 3)));
}

/* ── state & rendering ──────────────────────────────────────────── */
const figState = { unitIdx: 0, single: false, overlay: false, showHighlight: false };

function figRender() {
  figGrid.style.display = figState.single ? 'none' : 'grid';
  figSingleWrap.style.display = figState.single ? 'block' : 'none';
  if (figSingleChart) { figSingleChart.destroy(); figSingleChart = null; }
  if (figState.single) {
    figSingleChart = figMakeChart(figSingleCanvas, figState.unitIdx + 1, true, figState.overlay, true, true);
    figFadeIn(figSingleChart);
  } else {
    for (let i = 0; i < figCells.length; i++) {
      const on = figState.showHighlight && (i === figState.unitIdx + 1);
      figCells[i].style.background = on ? '#eaf5fb' : 'transparent';
      figCells[i].style.boxShadow = on ? '0 0 0 2px #7cc0e4' : 'none';
    }
    figGridCharts.forEach(function (c) { c.resize(); figApplySizes(c); });
  }
}

function figSelectPanel(idx) {
  figState.unitIdx = Math.max(0, Math.min(4, idx - 1));
  figState.single = true;
  figState.showHighlight = true;
  document.getElementById('hiddenUnitsInput').value = figState.unitIdx;
  document.getElementById('hiddenUnitsVal').value = FIG_UNITS[figState.unitIdx];
  document.getElementById('layoutInput').checked = true;
  figRender();
}

/* ── controls ───────────────────────────────────────────────────── */
function update_hiddenUnits(v) {
  figState.unitIdx = Math.max(0, Math.min(4, v | 0));
  figState.showHighlight = true;
  document.getElementById('hiddenUnitsVal').value = FIG_UNITS[figState.unitIdx];
  figRender();
}
function toggle_layout(on) { figState.single = !!on; figRender(); }
function toggle_overlay6vs50(on) {
  figState.overlay = !!on;
  if (on && !figState.single) {
    figState.single = true;
    document.getElementById('layoutInput').checked = true;
  }
  figRender();
}
function showKeyInsight() {
  showPopup('Key insight',
    'Over-parameterisation does not make a network wigglier. Every one of these models fits the same data points ' +
    'exactly, but the ones with far more hidden units than data choose the smoothest such function — so the 50-unit ' +
    'fit generalises best, while the barely-sufficient 6-unit fit flails in the region with no data.');
}

/* ── demo step player ───────────────────────────────────────────── */
const FIG_STEPS = [
  { title: 'The target and the data',
    narration: 'Panel a) shows the true function (black) and the training points (orange). Notice the points cluster at the two ends — the middle of the input range has no data at all.',
    state: { single: false, units: 0, overlay: false } },
  { title: 'Just enough capacity: 6 units',
    narration: 'With 6 hidden units the network still passes through every data point, but in the data-free middle it swings completely off the chart. The fit is not wrong at the data — it is unconstrained away from it.',
    state: { single: true, units: 0, overlay: false } },
  { title: 'Adding units: 7 and 8',
    narration: 'One or two extra units pull the excursions back on-scale, but the curve still overshoots the true peak and trough. More parameters are already making the function tamer, not wilder.',
    state: { single: true, units: 2, overlay: false } },
  { title: 'Plenty of capacity: 10 units',
    narration: 'At 10 units the piecewise-linear fit tracks the black curve across the whole domain, with only small kinks where the joints between linear regions sit.',
    state: { single: true, units: 3, overlay: false } },
  { title: 'Massive capacity: 50 units',
    narration: 'With 50 hidden units — far more parameters than data points — the fit is the smoothest of all and only just departs from the true function. The expected "overfitting explosion" never arrives.',
    state: { single: true, units: 4, overlay: false } },
  { title: 'Rough versus smooth, side by side',
    narration: 'Overlay the 6-unit and 50-unit solutions: both interpolate the same points, yet only the over-parameterised one behaves sensibly where there is no data.',
    state: { single: true, units: 4, overlay: true } },
  { title: 'The whole trend',
    narration: 'Back in the grid, read b) → f) as a single sequence: increasing capacity monotonically increases smoothness and fidelity to the truth.',
    state: { single: false, units: 4, overlay: false } }
];
let figStep = 0;

function figApplyStep(i) {
  figStep = ((i % FIG_STEPS.length) + FIG_STEPS.length) % FIG_STEPS.length;
  const st = FIG_STEPS[figStep].state;
  figState.unitIdx = st.units;
  figState.single = st.single;
  figState.overlay = st.overlay;
  figState.showHighlight = (figStep > 0);
  document.getElementById('hiddenUnitsInput').value = st.units;
  document.getElementById('hiddenUnitsVal').value = FIG_UNITS[st.units];
  document.getElementById('layoutInput').checked = figState.single;
  document.getElementById('overlay6vs50Input').checked = figState.overlay;
  document.getElementById('stepTitle').textContent = FIG_STEPS[figStep].title;
  document.getElementById('demoNarration').textContent = FIG_STEPS[figStep].narration;
  document.getElementById('stepLabel').textContent = (figStep + 1) + ' / ' + FIG_STEPS.length;
  figRender();
}
function nextStep() { figApplyStep(figStep + 1); }
function prevStep() { figApplyStep(figStep - 1); }

/* ── resize handling ────────────────────────────────────────────── */
let figResizeTimer = 0;
document.addEventListener('fig-resize', function () {
  clearTimeout(figResizeTimer);
  figResizeTimer = setTimeout(function () {
    figGridCharts.forEach(function (c) { c.resize(); figApplySizes(c); });
    if (figSingleChart) { figSingleChart.resize(); figApplySizes(figSingleChart); }
  }, 130);
});

figApplyStep(0);
window.__markRendered();
